/* Self-destroying service worker.
   The old Chirpy theme registered a service worker at /sw.min.js that cached the
   whole blog offline. This replacement unregisters it and clears those caches so
   returning visitors get the new site instead of the stale cached one. Safe to
   delete once enough time has passed that no old caches remain in the wild. */
self.addEventListener('install', function () {
  self.skipWaiting();
});

self.addEventListener('activate', function (event) {
  event.waitUntil((async function () {
    const keys = await caches.keys();
    await Promise.all(keys.map(function (k) { return caches.delete(k); }));
    await self.registration.unregister();
    const clients = await self.clients.matchAll({ type: 'window' });
    clients.forEach(function (client) { client.navigate(client.url); });
  })());
});
